    private static void insertNode(int record) {
        TreeNode targetNode = insertBST(redBlackTree ,record);
        balanceTree(targetNode);
    }

    private static TreeNode insertBST(TreeNode node, int record) {
        if(record < node.getRecord()) {
            if(node.getLeftChild().getRecord() == null) {
                node.getLeftChild().setRecord(record);
                node.getLeftChild().setParent(node);
                node.getLeftChild().setRed(true);
                node.getLeftChild().setLeftChild(new TreeNode(null, null, false));
                node.getLeftChild().setRightChild(new TreeNode(null, null, false));
                return node.getLeftChild();
            }
            return insertBST(node.getLeftChild(), record);
        }
        if(node.getRightChild().getRecord() == null) {
            node.getRightChild().setRecord(record);
            node.getRightChild().setParent(node);
            node.getRightChild().setRed(true);
            node.getRightChild().setLeftChild(new TreeNode(null, null, false));
            node.getRightChild().setRightChild(new TreeNode(null, null, false));
            return node.getRightChild();
        }
        return insertBST(node.getRightChild(), record);
    }

    private static void balanceTree(TreeNode targetNode) {
        while(targetNode.getParent() != null && targetNode.getParent().isRed()) {
            TreeNode parentNode = targetNode.getParent();
            TreeNode grandNode = parentNode.getParent();
            TreeNode uncleNode = null;
            if(parentNode.getRecord() > grandNode.getRecord()) {
                uncleNode = grandNode.getLeftChild();
            } else {
                uncleNode = grandNode.getRightChild();
            }
            if(parentNode == grandNode.getLeftChild()) {
                if(uncleNode.isRed()) {
                    parentNode.setRed(false);
                    uncleNode.setRed(false);
                    grandNode.setRed(true);
                    targetNode = grandNode;
                } else if(targetNode == parentNode.getRightChild()) {
                    targetNode = parentNode;
                    leftRotate(parentNode);
                } else if(targetNode == parentNode.getLeftChild()) {
                    parentNode.setRed(false);
                    grandNode.setRed(true);
                    rightRotate(grandNode);
                }
            } else {
                if(uncleNode.isRed()) {
                    parentNode.setRed(false);
                    uncleNode.setRed(false);
                    grandNode.setRed(true);
                    targetNode = grandNode;
                } else if(targetNode == parentNode.getLeftChild()) {
                    targetNode = parentNode;
                    rightRotate(parentNode);
                } else if(targetNode == parentNode.getRightChild()) {
                    parentNode.setRed(false);
                    grandNode.setRed(true);
                    leftRotate(grandNode);
                }
            }
        }
        redBlackTree.setRed(false);
    }

    private static void leftRotate(TreeNode targetNode) {
        TreeNode parentNode = targetNode.getParent();
        TreeNode rightNode = targetNode.getRightChild();
        TreeNode rightLeftNode = rightNode.getLeftChild();
        if(parentNode == null) {
            redBlackTree = rightNode;
            rightNode.setParent(null);
        } else if(targetNode.getRecord() > parentNode.getRecord()) {
            parentNode.setRightChild(rightNode);
            rightNode.setParent(parentNode);
        } else {
            parentNode.setLeftChild(rightNode);
            rightNode.setParent(parentNode);
        }
        rightNode.setLeftChild(targetNode);
        targetNode.setParent(rightNode);
        targetNode.setRightChild(rightLeftNode);
        rightLeftNode.setParent(targetNode);
    }

    private static void rightRotate(TreeNode targetNode) {
        TreeNode parentNode = targetNode.getParent();
        TreeNode leftNode = targetNode.getLeftChild();
        TreeNode leftRightNode = leftNode.getRightChild();
        if(parentNode == null) {
            redBlackTree = leftNode;
            leftNode.setParent(null);
        } else if(targetNode.getRecord() > parentNode.getRecord()) {
            parentNode.setRightChild(leftNode);
            leftNode.setParent(parentNode);
        } else {
            parentNode.setLeftChild(leftNode);
            leftNode.setParent(parentNode);
        }
        leftNode.setRightChild(targetNode);
        targetNode.setParent(leftNode);
        targetNode.setLeftChild(leftRightNode);
        leftRightNode.setParent(targetNode);
    }

    private static TreeNode searchTree(TreeNode node, int record) {
        if(node.getRecord() == null) {
            return null;
        }
        if(record == node.getRecord()) {
            return node;
        }
        if(record < node.getRecord()) {
            return searchTree(node.getLeftChild(), record);
        }
        return searchTree(node.getRightChild(), record);
    }

    private static void deleteNode(TreeNode targetNode) {
        TreeNode deletedNode = null;
        if(targetNode.getLeftChild().getRecord() == null || targetNode.getRightChild().getRecord() == null) {
            deletedNode = targetNode;
        } else {
            deletedNode = targetNode.getRightChild();
            while(deletedNode.getLeftChild().getRecord() != null) {
                deletedNode = deletedNode.getLeftChild();
            }
        }
        TreeNode childNode = null;
        if(deletedNode.getLeftChild().getRecord() != null) {
            childNode = deletedNode.getLeftChild();
        } else {
            childNode = deletedNode.getRightChild();
        }
        childNode.setParent(deletedNode.getParent());
        if(deletedNode.getParent() == null) {
            redBlackTree = deletedNode;
            redBlackTree.setRed(false);
        } else if(deletedNode == deletedNode.getParent().getLeftChild()) {
            deletedNode.getParent().setLeftChild(childNode);
        } else {
            deletedNode.getParent().setRightChild(childNode);
        }
        if(deletedNode != targetNode) {
            targetNode.setRecord(deletedNode.getRecord());
        }
        if(!deletedNode.isRed()) {
            balanceAfterDelete(childNode);
        }
    }

    private static void balanceAfterDelete(TreeNode targetNode) {
        while(targetNode != redBlackTree && (targetNode == null || !targetNode.isRed())) {
            if(targetNode == targetNode.getParent().getLeftChild()) {
                TreeNode siblingNode = targetNode.getParent().getRightChild();
                if(siblingNode.isRed()) {
                    siblingNode.setRed(false);
                    targetNode.getParent().setRed(true);
                    leftRotate(targetNode.getParent());
                    siblingNode = targetNode.getParent().getRightChild();
                } else if((siblingNode.getLeftChild() == null || !siblingNode.getLeftChild().isRed())
                        && (siblingNode.getRightChild() == null || !siblingNode.getRightChild().isRed())) {
                    siblingNode.setRed(true);
                    targetNode = targetNode.getParent();
                } else if(siblingNode.getRightChild() == null || !siblingNode.getRightChild().isRed()) {
                    siblingNode.getLeftChild().setRed(false);
                    siblingNode.setRed(true);
                    rightRotate(siblingNode);
                    siblingNode = targetNode.getParent().getRightChild();
                } else {
                    siblingNode.setRed(targetNode.getParent().isRed());
                    targetNode.getParent().setRed(false);
                    siblingNode.getRightChild().setRed(false);
                    leftRotate(targetNode.getParent());
                    targetNode = redBlackTree;
                }
            } else {
                TreeNode siblingNode = targetNode.getParent().getLeftChild();
                if(siblingNode.isRed()) {
                    siblingNode.setRed(false);
                    targetNode.getParent().setRed(true);
                    rightRotate(targetNode.getParent());
                    siblingNode = targetNode.getParent().getLeftChild();
                } else if((siblingNode.getRightChild() == null || !siblingNode.getRightChild().isRed())
                        && (siblingNode.getLeftChild() == null || !siblingNode.getLeftChild().isRed())) {
                    siblingNode.setRed(true);
                    targetNode = targetNode.getParent();
                } else if(siblingNode.getLeftChild() == null || !siblingNode.getLeftChild().isRed()) {
                    siblingNode.getRightChild().setRed(false);
                    siblingNode.setRed(true);
                    leftRotate(siblingNode);
                    siblingNode = targetNode.getParent().getLeftChild();
                } else {
                    siblingNode.setRed(targetNode.getParent().isRed());
                    targetNode.getParent().setRed(false);
                    siblingNode.getLeftChild().setRed(false);
                    rightRotate(targetNode.getParent());
                    targetNode = redBlackTree;
                }
            }
        }
        targetNode.setRed(false);
    }

    private static void sortBST(TreeNode node) {
        if(node.getRecord() != null) {
            sortBST(node.getLeftChild());
            allElements.add(node.getRecord());
            sortBST(node.getRightChild());
        }
    }

