                failure += 2 * tempTimes;
            } else if(node.getLeftChild().getRecord() == null || node.getRightChild().getRecord() == null) {
                nullNode++;
                failure += tempTimes;
            }
            return node;
        }
        if(record < node.getRecord()) {
            tempTimes++;
            return searchFailure(node.getLeftChild(), record);
        }
        tempTimes++;
        return searchFailure(node.getRightChild(), record);
    }

