        mInsertNode.setAccessible(true);
        mDeleteNode = Main.class.getDeclaredMethod("deleteNode", TreeNode.class);
        mDeleteNode.setAccessible(true);
        mSearchTree = Main.class.getDeclaredMethod("searchTree", TreeNode.class, int.class);
        mSearchTree.setAccessible(true);

        // seed root manually (buildTree reads order.txt; do it directly here)
        TreeNode root = new TreeNode(null, 1000);
        root.setRed(false);
        root.setLeftChild(new TreeNode(null, null, false));
        root.setRightChild(new TreeNode(null, null, false));
        fTree.set(null, root);

        TreeSet<Integer> ref = new TreeSet<>();
        ref.add(1000);
        Random rnd = new Random(42);

        // random inserts
        for (int i = 0; i < 5000; i++) {
            int v = rnd.nextInt(10000);
            if (!ref.contains(v)) {
                mInsertNode.invoke(null, v);
                ref.add(v);
                check(root(), ref, "insert " + v);
            }
        }
        // random deletes
        List<Integer> vals = new ArrayList<>(ref);
        Collections.shuffle(vals, rnd);
        for (int i = 0; i < 4000; i++) {
            int v = vals.get(i);
            TreeNode n = (TreeNode) mSearchTree.invoke(null, root(), v);
            if (n == null) throw new AssertionError("search failed for existing " + v);
            mDeleteNode.invoke(null, n);
            ref.remove(v);
            check(root(), ref, "delete " + v);
        }
        // search checks
        for (int v = 0; v < 10000; v += 7) {
            TreeNode n = (TreeNode) mSearchTree.invoke(null, root(), v);
            if ((n != null) != ref.contains(v))
                throw new AssertionError("search mismatch for " + v);
        }
        System.out.println("ALL CHECKS PASSED, remaining size=" + ref.size());
    }

    static TreeNode root() throws Exception { return (TreeNode) fTree.get(null); }

    static void check(TreeNode root, TreeSet<Integer> ref, String ctx) {
        if (root.isRed()) throw new AssertionError(ctx + ": root not black");
        if (root.getParent() != null) throw new AssertionError(ctx + ": root parent != null");
        List<Integer> in = new ArrayList<>();
        blackHeight(root, in, 0, null, ctx);
        if (!in.equals(new ArrayList<>(ref)))
            throw new AssertionError(ctx + ": in-order mismatch");
    }

    static int blackHeight(TreeNode n, List<Integer> in, int blacks, Integer parentBlack, String ctx) {
        if (n.getRecord() == null) {
            if (n.isRed()) throw new AssertionError(ctx + ": NIL red");
            return blacks + 1;
        }
        if (n.isRed()) {
            if (n.getLeftChild().isRed() || n.getRightChild().isRed())
                throw new AssertionError(ctx + ": red-red at " + n.getRecord());
        } else blacks++;
        int lb = blackHeight(n.getLeftChild(), in, blacks, null, ctx);
        in.add(n.getRecord());
        int rb = blackHeight(n.getRightChild(), in, blacks, null, ctx);
        if (lb != rb) throw new AssertionError(ctx + ": black-height mismatch at " + n.getRecord());
        // parent-link sanity
        if (n.getLeftChild().getRecord() != null && n.getLeftChild().getParent() != n)
            throw new AssertionError(ctx + ": bad parent link L at " + n.getRecord());
        if (n.getRightChild().getRecord() != null && n.getRightChild().getParent() != n)
            throw new AssertionError(ctx + ": bad parent link R at " + n.getRecord());
        return lb;
    }
}

